const char *path = "/tmp/link_file";
uid_t target_uid = 1001;
gid_t target_gid = 100;

// Set new owner (1001) and new group (100)
int res = lchown32(path, target_uid, target_gid);

// Set group only (owner remains unchanged: -1)
lchown32(path, (uid_t)-1, target_gid);

if (res == -1) {
    // Failure (check errno: EACCES, EPERM)
    // lchown32 operates on the link itself
}
